import csv
import io
import re


def _fallback_reader(text):
    rows = []
    row = []
    field = []
    in_quotes = False
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]

        if in_quotes:
            if ch == '"':
                if i + 1 < n and text[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                field.append(ch)
            i += 1
            continue

        if ch == '"' and not field:
            in_quotes = True
        elif ch == ',':
            row.append("".join(field))
            field = []
        elif ch == "\r" or ch == "\n":
            row.append("".join(field))
            field = []
            rows.append(row)
            row = []
            if ch == "\r" and i + 1 < n and text[i + 1] == "\n":
                i += 1
        else:
            field.append(ch)
        i += 1

    if field or row or (n > 0 and text[-1] == ","):
        row.append("".join(field))
        rows.append(row)

    return rows


def _read_rows(raw_csv):
    try:
        csv.field_size_limit(max(131072, len(raw_csv) + 1))
        return list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    except (csv.Error, TypeError, ValueError, OverflowError):
        return _fallback_reader(raw_csv)


def _normalized(value):
    return re.sub(r"[^a-z0-9]+", "", value.lstrip("\ufeff").strip().lower())


def _find_header(rows):
    expected = {
        "date", "time", "qty", "quantity", "productid", "price",
        "producttype", "productdescription", "url", "comments"
    }
    best_index = None
    best_score = -1

    for index, row in enumerate(rows):
        names = [_normalized(value) for value in row]
        matched = sum(1 for name in names if name in expected)
        required = int("date" in names) + int("time" in names)
        width_bonus = 3 if len(row) == 9 else 0
        score = matched * 4 + required * 3 + width_bonus

        if matched >= 5 and required == 2 and score > best_score:
            best_index = index
            best_score = score

    if best_index is not None:
        return best_index

    for index, row in enumerate(rows):
        if row and any(value != "" for value in row):
            return index

    return None


def _repair_row(row, columns):
    width = len(columns)
    values = list(row)
    names = [_normalized(column) for column in columns]

    try:
        date_index = names.index("date")
        time_index = names.index("time")
    except ValueError:
        date_index = -1
        time_index = -1

    if (
        len(values) > width
        and date_index >= 0
        and time_index == date_index + 1
    ):
        excess = len(values) - width
        last_candidate = min(len(values) - 1, time_index + excess)
        found_time = None
        for index in range(time_index, last_candidate + 1):
            if re.fullmatch(
                r"\s*(?:[01]?\d|2[0-3]):[0-5]\d(?:\:[0-5]\d(?:\.\d+)?)?\s*",
                values[index],
            ):
                found_time = index
                break

        if found_time is not None and found_time > time_index:
            merged_date = ",".join(values[date_index:found_time])
            values = values[:date_index] + [merged_date] + values[found_time:]

    if len(values) > width:
        try:
            description_index = names.index("productdescription")
            url_index = names.index("url")
            comments_index = names.index("comments")
        except ValueError:
            description_index = -1
            url_index = -1
            comments_index = -1

        actual_url_index = None
        if description_index >= 0 and url_index > description_index:
            for index in range(description_index + 1, len(values)):
                if re.match(
                    r"^\s*[A-Za-z][A-Za-z0-9+.-]*://",
                    values[index],
                ):
                    actual_url_index = index
                    break

        if (
            actual_url_index is not None
            and comments_index == url_index + 1
            and actual_url_index >= description_index + 1
        ):
            prefix = values[:description_index]
            description = ",".join(values[description_index:actual_url_index])
            url = values[actual_url_index]
            comments = ",".join(values[actual_url_index + 1:])
            values = prefix + [description, url, comments]

    if len(values) > width:
        values = values[:width - 1] + [",".join(values[width - 1:])]

    if len(values) < width:
        values.extend([""] * (width - len(values)))

    return values


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    rows = _read_rows(raw_csv)
    header_index = _find_header(rows)

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = list(rows[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    repaired_rows = [
        _repair_row(row, columns)
        for row in rows[header_index + 1:]
    ]

    return {"columns": columns, "rows": repaired_rows}
